import {catalogNav,guideMarkup,bindGuide,catalog} from './writing-catalog.mjs';
import {projects} from './state.mjs';
import {registerEditor,markEditorSaved} from './edit-guard.mjs';
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export const supportFields={
 taskbook:[['goals','研究目标'],['content','研究内容与任务'],['method','研究方法与资料来源'],['schedule','计划安排'],['deliverable','预期成果']],
 practice:[['unit','实践单位'],['position','岗位'],['start','开始日期','date'],['end','结束日期','date'],['experience','实际工作内容与经历'],['reflection','收获与反思']],
 idea:[['major','专业'],['interest','研究兴趣'],['question','核心研究问题'],['data','可获得的数据与材料'],['method','拟采用的方法'],['deliverable','预期成果']],
 questionnaire:[['goal','研究目标'],['population','目标人群'],['dimensions','调查维度'],['instructions','答题说明'],['questions','问题与选项（每行记录一个问题，可在右侧编辑）']],
 analysis:[['question','研究问题'],['source','真实数据来源'],['variables','变量与类型'],['quality','样本、缺失值与清理说明'],['method','预期分析方法'],['existing','已有计算结果（可选，注明计算工具）']]
};
const boundaries={questionnaire:'本地问卷草稿 · 在线发布、二维码、答卷回收与信效度计算尚未接入。',analysis:'本地分析计划 · 当前不执行统计运算，不输出虚构 p 值、回归系数或分析结论。',practice:'本地报告框架 · 请填写真实实践经历，当前未调用 AI。',idea:'本地课题思路框架 · 不自动检索文献或评估创新性。',taskbook:'本地任务书框架 · 根据学校与导师要求人工核对，当前未调用 AI。'};
export function supportText(kind,v){const title=v.title||'未命名任务';const name=catalog.find(t=>t[0]===kind)?.[1]||kind;return [title,name+' · 本地整理',...supportFields[kind].flatMap(([key,label])=>['',label,v[key]?.trim()||'（待填写真实内容）']),'',boundaries[kind]].join('\n');}
export function mountWritingSupport(kind,draftId,projectId,ctx){if(!supportFields[kind])return false;let drafts=[];try{drafts=JSON.parse(localStorage.getItem('paperknow-drafts')||'[]');}catch{}if(!Array.isArray(drafts))drafts=[];const loaded=drafts.find(d=>String(d.id)===String(draftId));let savedId=loaded?.id;const name=catalog.find(t=>t[0]===kind)[1],fields=loaded?.supportFields||{},main=document.querySelector('.dashboard');main.classList.add('creation-page');main.classList.remove('category-view');main.innerHTML=`<div class="creation-heading"><div><h1>${name}</h1><p>准备真实信息，整理结构后编辑与导出。</p></div><a class="btn secondary" href="#assets">写作记录</a></div>${catalogNav(kind)}${guideMarkup(kind)}<div class="support-boundary" role="note">${boundaries[kind]}</div><div class="creation-grid"><section class="card creation-input"><h2>任务信息</h2><form id="support-form"><label for="support-project">所属项目（可选）</label><select id="support-project"><option value="">未归入项目</option>${projects().map(p=>`<option value="${esc(p.id)}" ${p.id===(loaded?.projectId||projectId)?'selected':''}>${esc(p.name)}</option>`).join('')}</select><label for="support-title">题目 / 主题 *</label><input id="support-title" required minlength="2" maxlength="200" value="${esc(loaded?.title||'')}">${supportFields[kind].map(([key,label,type])=>`<label for="support-${key}">${label}</label>${type?`<input id="support-${key}" type="${type}" value="${esc(fields[key]||'')}">`:`<textarea id="support-${key}" rows="3" maxlength="5000">${esc(fields[key]||'')}</textarea>`}`).join('')}<p id="support-error" role="alert"></p><button class="btn primary" type="submit">整理本地框架 →</button></form></section><section class="card creation-output"><h2>草稿与编辑</h2><p>以下仅整理你输入的内容；未填写的信息保持待填写。</p><label for="support-output">编辑任务内容</label><textarea id="support-output" rows="23" maxlength="100000">${esc(loaded?.text||'')}</textarea><div class="creation-actions"><button id="support-save" class="btn secondary">保存草稿</button><button id="support-export" class="btn primary">导出 TXT</button></div><p id="support-status" role="status"></p></section></div>`;
const $=s=>document.querySelector(s);const values=()=>({title:$('#support-title').value.trim(),...Object.fromEntries(supportFields[kind].map(([key])=>[key,$('#support-'+key).value]))});bindGuide();
$('#support-form').onsubmit=e=>{e.preventDefault();const v=values();if(kind==='practice'&&v.start&&v.end&&v.end<v.start){$('#support-error').textContent='结束日期不能早于开始日期。';return;}$('#support-error').textContent='';if($('#support-output').value.trim()){ctx.modal('保留当前草稿',`<p>整理框架会替换右侧内容。请先保存或导出；确认后再替换。</p><button class="btn primary" id="support-replace">确认替换框架</button>`);$('#support-replace').onclick=()=>{$('#support-output').value=supportText(kind,v);document.querySelector('#workspace-dialog')?.close();};return;}$('#support-output').value=supportText(kind,v);$('#support-status').textContent='框架已整理，请根据实际材料编辑。';};
$('#support-save').onclick=()=>{if(!$('#support-form').reportValidity())return;let rows=[];try{rows=JSON.parse(localStorage.getItem('paperknow-drafts')||'[]');if(!Array.isArray(rows))throw Error();const v=values();if(v.title.length<2){$('#support-error').textContent='请填写至少 2 个字的题目或主题。';return;}if(kind==='practice'&&v.start&&v.end&&v.end<v.start){$('#support-error').textContent='结束日期不能早于开始日期。';return;}const now=new Date().toISOString(),text=$('#support-output').value,previous=rows.find(d=>d.id===savedId)||loaded;const item={...previous,id:savedId||crypto.randomUUID(),title:v.title,tool:kind,projectId:$('#support-project').value,supportFields:v,text,html:text.split('\n').map(l=>`<p>${esc(l)}</p>`).join(''),createdAt:previous?.createdAt||now,updatedAt:now,stage:'draft'};const i=rows.findIndex(d=>d.id===item.id);if(i<0)rows.unshift(item);else rows[i]=item;localStorage.setItem('paperknow-drafts',JSON.stringify(rows));savedId=item.id;markEditorSaved();$('#support-status').textContent='草稿已保存到当前浏览器。';}catch{$('#support-status').textContent='保存失败，请先导出备份。';}};
$('#support-export').onclick=()=>{const text=$('#support-output').value;if(!text.trim()){ $('#support-status').textContent='请先整理框架或填写内容。';return;}const url=URL.createObjectURL(new Blob([text],{type:'text/plain;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download=(values().title||name).replace(/[\\/:*?"<>|]/g,'_')+'.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),10000);$('#support-status').textContent='已发起 TXT 下载。';};
if(ctx)registerEditor({label:name+'草稿',ctx,getValue:()=>({...values(),projectId:$('#support-project').value,text:$('#support-output').value}),save:()=>$('#support-save').click()});return true;}
